pluginManagement {
  repositories {
    google {
      content {
        includeGroupByRegex("com\\.android.*")
        includeGroupByRegex("com\\.google.*")
        includeGroupByRegex("androidx.*")
      }
    }
    mavenCentral()
    gradlePluginPortal()
  }
}

plugins { id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0" }

dependencyResolutionManagement {
  repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
  repositories {
    google()
    mavenCentral()
  }
}

val debugKeystoreFile = java.io.File(rootDir, "debug.keystore")
if (!debugKeystoreFile.exists()) {
  val b64File = java.io.File(rootDir, "debug.keystore.base64")
  val b64Content = if (b64File.exists()) {
    b64File.readText().replace("\\s".toRegex(), "")
  } else {
    ""
  }
  debugKeystoreFile.writeBytes(java.util.Base64.getDecoder().decode(b64Content))
}

rootProject.name = "Pyraminds"

include(":app")
